B.aiU=s(["2 rebanadas de pan","2 huevos","1 cucharadita de aceite de oliva","Sal","Opcional: jam\xf3n york o queso"],t.s)
B.aif=s(["Tuesta el pan.","Bate los huevos con una pizca de sal.","Calienta una cucharadita de aceite en una sart\xe9n a fuego medio.","Echa los huevos y remueve sin parar con una esp\xe1tula 2-3 minutos, hasta que cuajen pero sigan jugosos.","Pon un chorrito de aceite en las tostadas y los huevos encima."],t.s)
B.aTc=new A.aT("tostadas-huevos","Tostadas con huevos revueltos",8,"1 raci\xf3n",B.aiU,B.aif,"Con prisa: bate los huevos en una taza y cali\xe9ntalos en el microondas en tandas de 30 segundos, removiendo entre medias. O usa 2 huevos cocidos el d\xeda de la compra.",370,20,B.cE,B.cn,!1)
B.amb=s(["50 g de copos de avena","300 ml de leche entera","1 pl\xe1tano","20 g de nueces","1 cucharada de miel"],t.s)
B.aGk=s(["Pon la avena y la leche en un bol.","Calienta 2 minutos en el microondas (o en un cazo, removiendo).","A\xf1ade el pl\xe1tano en rodajas, las nueces troceadas y la miel."],t.s)
B.aST=new A.aT("avena","Avena con leche, pl\xe1tano, nueces y miel",5,"1 raci\xf3n",B.amb,B.aGk,"Puedes dejarla preparada la noche antes en la nevera y tomarla fr\xeda.",660,21,B.cE,B.cn,!1)
B.azU=s(["40 g de copos de avena","2 huevos","1 pl\xe1tano maduro","Unas gotas de aceite","Miel para servir"],t.s)
B.amT=s(["Tritura la avena, los huevos y el pl\xe1tano hasta tener una masa espesa.",u.s,"Echa un cuchar\xf3n de masa por tortita.","Cuando salgan burbujas (1-2 minutos), dale la vuelta y deja 1 minuto m\xe1s.","S\xedrvelas con miel."],t.s)
B.aTh=new A.aT("tortitas-avena","Tortitas de avena",15,"1 raci\xf3n (4-5 tortitas)",B.azU,B.amT,"Fuego bajo: si est\xe1 muy fuerte se queman por fuera y quedan crudas por dentro.",440,22,B.cE,B.cn,!1)
B.aeH=s(["90 g de macarrones","120 g de carne picada de ternera","100 g de tomate frito","1 cucharadita de aceite de oliva","Sal","Opcional: queso rallado"],t.s)
B.ajk=s(["Hierve agua con sal y cuece los macarrones el tiempo que diga el paquete (10-12 minutos).","Mientras, dora la carne en una sart\xe9n con un chorrito de aceite y sal, deshaci\xe9ndola con la esp\xe1tula, 5-6 minutos.","A\xf1ade el tomate frito y deja 3 minutos a fuego bajo.",u.F],t.s)
B.aSY=new A.aT("macarrones-carne","Macarrones con carne picada y tomate",20,"1 raci\xf3n",B.aeH,B.ajk,"Si un d\xeda te animas, ralla medio calabac\xedn dentro de la salsa: no se nota.",720,34,B.Z,B.ci,!1)
B.amz=s(["170 g de pechuga de pollo","80 g de arroz","1 cucharadita de aceite de oliva","Sal","Ajo en polvo o piment\xf3n"],t.s)
B.arj=s(["Cuece el arroz en agua con sal 15-18 minutos (o usa el arroz que dejaste cocido el d\xeda de la compra).","Filetea la pechuga fina y saz\xf3nala.","Calienta bien la plancha con unas gotas de aceite y haz el pollo 3-4 minutos por lado, hasta que no quede rosa por dentro.","S\xedrvelo con el arroz y un chorrito de aceite."],t.s)
B.aTw=new A.aT("pollo-arroz","Pechuga de pollo a la plancha con arroz",20,"1 raci\xf3n",B.amz,B.arj,"El arroz cocido aguanta 3-4 d\xedas en t\xe1per en la nevera.",510,45,B.Z,B.d5,!1)
B.ahU=s(["1 kg de calabaza pelada","2 patatas","1 quesito por raci\xf3n (opcional)","Aceite de oliva","Sal"],t.s)
B.ahw=s(["Pela la calabaza y las patatas y c\xf3rtalas en dados.","Ponlas en una olla, c\xfabrelas de agua y a\xf1ade sal y un chorrito de aceite.","Cuece 20-25 minutos, hasta que est\xe9n blandas.","Quita parte del agua y tritura con la batidora hasta que quede cremosa.","Al servir, a\xf1ade un quesito y remueve."],t.s)
B.aTz=new A.aT("crema-calabaza","Crema de calabaza",35,"4 raciones",B.ahU,B.ahw,"Gu\xe1rdala en t\xe1pers de una raci\xf3n: 4 d\xedas en la nevera o 3 meses en el congelador. Sin tiempo, c\xf3mprala en brick.",170,5,B.Z,B.e1,!1)
B.atI=s(["3 calabacines","1 patata","2-3 quesitos","Aceite de oliva","Sal"],t.s)
B.ae9=s(["Lava los calabacines (no hace falta pelarlos) y c\xf3rtalos en trozos. Pela y trocea la patata.","C\xfabrelos de agua en una olla con sal y un chorrito de aceite.","Cuece 15-20 minutos.","Quita parte del agua, a\xf1ade los quesitos y tritura hasta que quede fina."],t.s)
B.aU2=new A.aT("crema-calabacin","Crema de calabac\xedn",25,"3 raciones",B.atI,B.ae9,"Los quesitos le quitan el sabor a verdura y le dan cuerpo.",160,6,B.Z,B.e1,!1)
B.ae7=s(["80 g de arroz","150 g de pollo en dados","80 g de jud\xedas verdes congeladas","2 cucharadas de tomate frito","300 ml de agua o caldo","1 cucharadita de aceite, sal y piment\xf3n"],t.s)
B.aoo=s(["Dora el pollo en una cazuela con aceite y sal, 5 minutos.","A\xf1ade las jud\xedas y el tomate frito y rehoga 2 minutos.","Echa el arroz y una pizca de piment\xf3n y remueve 1 minuto.","A\xf1ade el agua caliente y cuece 15-18 minutos a fuego medio sin remover.","Deja reposar 5 minutos tapado."],t.s)
B.aTb=new A.aT("arroz-pollo","Arroz con pollo y jud\xedas verdes",30,"1 raci\xf3n",B.ae7,B.aoo,null,640,39,B.Z,B.ci,!1)
B.ald=s(["1 lomo de salm\xf3n (descongelado la noche antes)","1 patata grande","1 cucharadita de aceite de oliva","Sal","Opcional: lim\xf3n"],t.s)
B.azN=s(["Precalienta el horno a 200 \xb0C.","Lava la patata, c\xf3rtala en gajos, ponle aceite y sal y horn\xe9ala 25 minutos.","A\xf1ade el salm\xf3n a la bandeja con sal y aceite y hornea 12-15 minutos m\xe1s.","Est\xe1 hecho cuando se separa en l\xe1minas con el tenedor."],t.s)
B.aTd=new A.aT("salmon-patata","Salm\xf3n al horno con patata asada",40,"1 raci\xf3n",B.ald,B.azN,"Para ir m\xe1s r\xe1pido: pincha la patata y dale 8 minutos de microondas antes de hornearla.",560,36,B.Z,B.f2,!1)
B.asp=s(["90 g de espaguetis","40 g de bacon","1 huevo + 1 yema","20 g de queso rallado","Pimienta","Sal"],t.s)
B.amK=s(["Cuece la pasta en agua con sal.","Dora el bacon en taquitos en una sart\xe9n sin aceite, 4 minutos.","Bate el huevo, la yema y el queso con pimienta.","Escurre la pasta guardando medio vaso del agua de cocerla.","Fuera del fuego, mezcla la pasta con el bacon y a\xf1ade el huevo removiendo r\xe1pido, con un poco del agua, hasta que quede cremoso."],t.s)
B.aSU=new A.aT("carbonara","Espaguetis carbonara",15,"1 raci\xf3n",B.asp,B.amK,"Siempre fuera del fuego: si no, el huevo se cuaja y queda como un revuelto.",640,29,B.Z,B.ci,!1)
B.agD=s(["3 huevos","1 patata grande","Aceite de oliva","Sal"],t.s)
B.am_=s(["Pela las patatas y c\xf3rtalas en l\xe1minas finas.","Fr\xedelas en una sart\xe9n con bastante aceite a fuego medio 15 minutos, hasta que est\xe9n tiernas.","Esc\xfarrelas y m\xe9zclalas con los huevos batidos y sal.","En una sart\xe9n peque\xf1a con 1 cucharada de aceite, echa la mezcla y cuaja 3-4 minutos.","Dale la vuelta con ayuda de un plato y deja 2 minutos m\xe1s."],t.s)
B.aTT=new A.aT("tortilla-patata","Tortilla de patata",30,"1 raci\xf3n grande",B.agD,B.am_,"M\xe1s r\xe1pido y con menos aceite: haz las patatas 6-7 minutos en el microondas, tapadas, en vez de fre\xedrlas.",600,28,B.Z,B.e1,!1)
B.afZ=s(["150 g de lomo de cerdo en filetes","100 ml de salsa de champi\xf1\xf3n de bote","1 patata grande","1 cucharadita de aceite de oliva","Sal"],t.s)
B.aeu=s([u.m,"Sazona los filetes y d\xf3ralos a fuego fuerte 2 minutos por lado.","Baja el fuego, a\xf1ade la salsa y deja 3-4 minutos.","S\xedrvelo con las patatas."],t.s)
B.aTi=new A.aT("lomo-champinon","Lomo en salsa de champi\xf1\xf3n con patatas al horno",35,"1 raci\xf3n",B.afZ,B.aeu,"Se puede hacer por lotes el jueves y guardar 3 d\xedas en la nevera.",560,39,B.Z,B.d5,!1)
B.aqo=s(["180 g de merluza (descongelada la noche antes)","80 g de arroz","1 cucharadita de aceite de oliva","Sal","Ajo en polvo","Opcional: lim\xf3n"],t.s)
B.auF=s(["Cuece el arroz o usa el que tengas cocido.","Seca bien la merluza con papel de cocina y saz\xf3nala.","Hazla en la plancha con aceite, primero por el lado de la piel 4 minutos y luego 2-3 minutos por el otro.","S\xedrvela con el arroz y un chorrito de aceite."],t.s)
B.aT6=new A.aT("merluza-arroz","Merluza a la plancha con arroz",20,"1 raci\xf3n",B.aqo,B.auF,null,470,36,B.Z,B.f2,!1)
B.ajM=s(["90 g de pasta (h\xe9lices o macarrones)","2 latas de at\xfan","3 cucharadas de ma\xedz","8 aceitunas","\xbd pepino (opcional)","2 cucharaditas de aceite de oliva","Sal"],t.s)
B.ax6=s(["Cuece la pasta, esc\xfarrela y enfr\xedala con agua fr\xeda.","M\xe9zclala con el at\xfan escurrido, el ma\xedz, las aceitunas en rodajas y el pepino en dados.","Ali\xf1a con aceite y sal.","Gu\xe1rdala en un t\xe1per en la nevera."],t.s)
B.aSQ=new A.aT("ensalada-pasta","Ensalada de pasta con at\xfan, ma\xedz y aceitunas",15,"1 t\xe1per",B.ajM,B.ax6,"Aguanta 2 d\xedas en la nevera. Ideal para d\xedas de evento.",730,42,B.Z,B.ey,!1)
B.amX=s(["3 huevos","Sal","1 cucharadita de aceite","Opcional: queso o jam\xf3n"],t.s)
B.akT=s(["Bate los huevos con sal.","Calienta el aceite en una sart\xe9n a fuego medio.","Echa los huevos y, cuando cuajen los bordes, dobla la tortilla por la mitad.","Deja 30 segundos m\xe1s y s\xedrvela."],t.s)
B.aTm=new A.aT("tortilla-francesa","Tortilla francesa",5,"1 raci\xf3n",B.amX,B.akT,null,300,23,B.Z,B.e1,!1)
B.aw_=s(["1-2 hamburguesas de ternera","1 pan de hamburguesa o 2 rebanadas","1 loncha de queso","Tomate frito o tu salsa","1 patata mediana","1 cucharadita de aceite de oliva","Sal"],t.s)
B.aiv=s([u.m,"Haz la hamburguesa en la plancha bien caliente, 3-4 minutos por lado.","Pon el queso encima el \xfaltimo minuto para que se funda.","Monta la hamburguesa en el pan con la salsa."],t.s)
B.aTf=new A.aT("hamburguesa","Hamburguesa casera con queso y patatas al horno",35,"1 raci\xf3n",B.aw_,B.aiv,null,750,37,B.Z,B.d5,!1)
B.aeE=s(["1-2 tortillas de wrap","120 g de pollo en tiras","1 loncha de queso","2 cucharadas de ma\xedz","\xbc de pepino en tiras","1 cucharadita de aceite, sal y piment\xf3n"],t.s)
B.auk=s(["Saltea el pollo con aceite, sal y piment\xf3n 6-7 minutos.","Calienta la tortilla 20 segundos en una sart\xe9n.","Rell\xe9nala con el pollo, el queso, el ma\xedz y el pepino.","Enr\xf3llala doblando primero los extremos."],t.s)
B.aTu=new A.aT("wrap-pollo","Wrap de pollo con queso, ma\xedz y pepino",15,"1 raci\xf3n",B.aeE,B.auk,"Envuelto en papel de aluminio sirve para llevar.",530,35,B.Z,B.ey,!1)
B.ahc=s(["200 g de arroz","200 g de pollo troceado","100 g de lomo o costilla de cerdo","100 g de jud\xedas verdes","2 cucharadas de tomate frito","800 ml de agua o caldo","Aceite, sal, piment\xf3n","Colorante o azafr\xe1n"],t.s)
B.ahM=s(["Dora la carne en la paellera con aceite y sal, 8 minutos.","A\xf1ade las jud\xedas y rehoga 3 minutos.","A\xf1ade el tomate y el piment\xf3n y remueve 1 minuto.","Echa el agua caliente y el colorante y deja que hierva.","Reparte el arroz: 10 minutos a fuego fuerte y 8 a fuego suave, sin remover.","Deja reposar 5 minutos tapada con un trapo."],t.s)
B.aTO=new A.aT("paella",u.h,45,"2 raciones",B.ahc,B.ahM,"La segunda raci\xf3n, a un t\xe1per para otro d\xeda o al congelador.",740,37,B.Z,B.ci,!1)
B.ai2=s(["90 g de pasta","2 latas de at\xfan","100 g de tomate frito","Opcional: queso rallado"],t.s)
B.ajt=s(["Cuece la pasta en agua con sal.","Calienta el tomate con el at\xfan escurrido 2 minutos.",u.F],t.s)
B.aT9=new A.aT("pasta-atun","Pasta con tomate y at\xfan",15,"1 raci\xf3n",B.ai2,B.ajt,null,640,42,B.Z,B.ci,!1)
B.aEp=s(["200 g de fideos de fideu\xe1 (del n.\xba 0 o del 1)","600 ml de fumet de pescado (de brick o casero)","200 g de gambas peladas","150 g de sepia o calamar en trozos","1 tomate maduro rallado","2 dientes de ajo picados","1 cucharadita de piment\xf3n dulce","Unas hebras de azafr\xe1n o colorante (opcional)","3 cucharadas de aceite de oliva","Sal","Alioli y lim\xf3n para servir"],t.s)
B.aFd=s(["Calienta el fumet en un cazo y d\xe9jalo a fuego m\xednimo. Tiene que estar muy caliente cuando lo eches.","En una paellera o sart\xe9n grande, calienta el aceite y dora la sepia 3-4 minutos. A\xf1ade las gambas, salt\xe9alas 1 minuto, s\xe1calas y res\xe9rvalas (la sepia se queda).","Echa el ajo y, antes de que se dore, el tomate rallado. Sofr\xede 5 minutos a fuego medio hasta que pierda el agua.","A\xf1ade los fideos y tu\xe9stalos 2-3 minutos removiendo, hasta que cojan color dorado.","Pon el piment\xf3n, remueve 10 segundos (sin que se queme) y echa 500 ml de fumet caliente con el azafr\xe1n. Prueba de sal.","Cocina a fuego medio-fuerte 8-10 minutos sin remover. Si se queda seco antes de tiempo, a\xf1ade un poco del fumet que sobra.","Cuando falten 2 minutos, reparte las gambas por encima.","Apaga y deja reposar 3 minutos tapada con un pa\xf1o. Si te gustan los fideos de punta, m\xe9tela 3-4 minutos al grill del horno.","Sirve con alioli y un chorro de lim\xf3n."],t.s)
B.aSV=new A.aT("fideua","Fideu\xe1 de pescado y marisco",35,"2 raciones",B.aEp,B.aFd,"La proporci\xf3n es de 2,5 veces de fumet por el peso de fideos. Para ganar peso, acomp\xe1\xf1ala de pan y una cucharada de alioli (+100 kcal).",710,45,B.Z,B.ci,!1)
B.akw=s(["250 g de lentejas pardinas","1 chorizo (unos 100 g) en rodajas","1 cebolla","1 zanahoria","1 pimiento verde","2 dientes de ajo","1 patata mediana","1 cucharadita de piment\xf3n dulce","1 hoja de laurel","2 cucharadas de aceite de oliva","Sal"],t.s)
B.atj=s(["Lava las lentejas en un colador (las pardinas no necesitan remojo).","Pica la cebolla, el pimiento, el ajo y la zanahoria en trozos peque\xf1os.","En una olla con el aceite, sofr\xede las verduras 8 minutos a fuego medio.","A\xf1ade el chorizo y deja 2 minutos para que suelte su grasa.","Echa el piment\xf3n, remueve r\xe1pido y a\xf1ade las lentejas, el laurel y agua hasta cubrirlas dos dedos.","Cuando hierva, baja el fuego, a\xf1ade la patata en trozos (cascados, no cortados del todo) y cuece 30-35 minutos.","Prueba de sal al final y deja reposar 5 minutos."],t.s)
B.aTg=new A.aT("lentejas","Lentejas con chorizo y verduras",45,"3 raciones",B.akw,B.atj,"Al d\xeda siguiente est\xe1n a\xfan mejor. Cong\xe9lalas en t\xe1pers de una raci\xf3n.",620,31,B.Z,B.ex,!1)
B.aFs=s(["1 bote de garbanzos cocidos (400 g)","200 g de espinacas frescas o congeladas","2 huevos","2 dientes de ajo","1 rebanada de pan","1 cucharadita de comino (opcional)","1 cucharadita de piment\xf3n","3 cucharadas de aceite de oliva","Sal"],t.s)
B.atb=s(["Cuece los huevos 10 minutos, enfr\xedalos y p\xe9lalos.","Lava los garbanzos del bote con agua y esc\xfarrelos.","En una sart\xe9n con el aceite, fr\xede los ajos laminados y la rebanada de pan hasta que est\xe9n dorados. S\xe1calos y m\xe1jalos con un tenedor.","En ese aceite, saltea las espinacas hasta que se reduzcan.","A\xf1ade los garbanzos, el majado, el comino, el piment\xf3n y un vaso peque\xf1o de agua. Cocina 5 minutos.","Sirve con los huevos en cuartos por encima."],t.s)
B.aTe=new A.aT("garbanzos-espinacas","Garbanzos con espinacas y huevo",20,"2 raciones",B.aFs,B.atb,null,520,24,B.Z,B.ex,!1)
B.alu=s(["350 g de pechuga o contramuslo de pollo","160 g de arroz (en crudo)","1 cebolla","1 lata de leche de coco (o 200 ml de nata para cocinar)","1 cucharada de curry en polvo","2 cucharadas de tomate frito","1 cucharada de aceite","Sal"],t.s)
B.ami=s(["Pon a cocer el arroz en agua con sal (15-18 minutos) y esc\xfarrelo.","Corta el pollo en dados y la cebolla en trozos peque\xf1os.","Dora el pollo en una sart\xe9n con el aceite, 5 minutos. S\xe1calo.","En la misma sart\xe9n pocha la cebolla 5 minutos, a\xf1ade el curry y remueve 30 segundos.","A\xf1ade la leche de coco y el tomate frito, vuelve a meter el pollo y cocina 8-10 minutos a fuego suave.","Sirve el pollo con su salsa sobre el arroz."],t.s)
B.aT_=new A.aT("pollo-curry","Pollo al curry con arroz",30,"2 raciones",B.alu,B.ami,"Con leche de coco tiene m\xe1s calor\xedas que con nata ligera: perfecto para ganar peso.",930,51,B.Z,B.d5,!1)
B.agb=s(["500 g de carne picada (mixta o de ternera)","1 huevo","2 cucharadas de pan rallado","1 diente de ajo picado y perejil","Harina para rebozar","1 cebolla","400 g de tomate triturado","1 vaso peque\xf1o de caldo o agua","Aceite de oliva y sal"],t.s)
B.aj0=s(["Mezcla la carne con el huevo, el pan rallado, el ajo, el perejil y sal.","Haz bolas del tama\xf1o de una nuez y p\xe1salas por harina.","Fr\xedelas en una sart\xe9n con un dedo de aceite hasta que est\xe9n doradas. S\xe1calas.","Quita casi todo el aceite y pocha la cebolla picada 5 minutos.","A\xf1ade el tomate y el caldo, cocina 10 minutos y mete las alb\xf3ndigas.","Cocina todo junto 10-15 minutos a fuego suave. Sirve con arroz, patatas o pan."],t.s)
B.aSS=new A.aT("albondigas","Alb\xf3ndigas en salsa de tomate",40,"3 raciones",B.agb,B.aj0,null,550,36,B.Z,B.d5,!1)
B.au8=s(["90 g de arroz (en crudo)","2 huevos","1 pl\xe1tano","4 cucharadas de tomate frito","Aceite de oliva","Sal"],t.s)
B.aG6=s(["Cuece el arroz en agua con sal 15-18 minutos y esc\xfarrelo.","Calienta el tomate frito.","Corta el pl\xe1tano a lo largo y d\xf3ralo en una sart\xe9n con unas gotas de aceite.","Fr\xede los huevos.","Monta el plato: arroz, tomate por encima, los huevos y el pl\xe1tano al lado."],t.s)
B.aTB=new A.aT("arroz-cubana","Arroz a la cubana",25,"1 raci\xf3n",B.au8,B.aG6,null,760,24,B.Z,B.ci,!1)
B.ah_=s(["200 g de espaguetis","250 g de carne picada de ternera","1 cebolla","1 zanahoria","400 g de tomate triturado","1 cucharadita de or\xe9gano","Queso rallado","Aceite de oliva y sal"],t.s)
B.ahv=s(["Pica la cebolla y ralla la zanahoria. Sofr\xedelas 6 minutos con aceite.","A\xf1ade la carne, sube el fuego y deshazla con la cuchara hasta que no quede rosa.","Echa el tomate, el or\xe9gano y sal. Cocina 15 minutos a fuego suave.","Mientras, cuece los espaguetis en agua con sal el tiempo del paquete.","Mezcla la pasta con la salsa y sirve con queso rallado."],t.s)
B.aTx=new A.aT("espaguetis-bolonesa","Espaguetis a la bolo\xf1esa",30,"2 raciones",B.ah_,B.ahv,"Haz el doble de salsa y cong\xe9lala: tienes otra comida en 10 minutos.",850,41,B.Z,B.ci,!1)
B.asz=s(["4 muslos o contramuslos de pollo","3 patatas medianas","1 cebolla","1 lim\xf3n","3 dientes de ajo","Romero o tomillo","3 cucharadas de aceite de oliva","Sal y pimienta"],t.s)
B.awJ=s(["Precalienta el horno a 200 \xb0C.","Corta las patatas en rodajas finas y la cebolla en tiras. Ponlas en la bandeja con sal y la mitad del aceite.","Coloca el pollo encima con la piel hacia arriba, los ajos chafados, el lim\xf3n en rodajas, las hierbas, sal, pimienta y el resto del aceite.","Hornea 45-50 minutos, hasta que la piel est\xe9 dorada y las patatas tiernas."],t.s)
B.aU4=new A.aT("muslos-horno","Muslos de pollo al horno con patatas",55,"2 raciones",B.asz,B.awJ,"Mientras se hace no tienes que hacer nada: ideal para los d\xedas de entreno.",890,47,B.Z,B.d5,!1)
B.aiT=s(["1 calabac\xedn","1 pimiento rojo y 1 verde","1 cebolla","400 g de tomate triturado","2 huevos","Pan para acompa\xf1ar","Aceite de oliva, sal y una pizca de az\xfacar"],t.s)
B.agE=s(["Corta todas las verduras en dados peque\xf1os.","Pocha la cebolla y los pimientos con aceite 10 minutos.","A\xf1ade el calabac\xedn y cocina 5 minutos m\xe1s.","Echa el tomate, sal y la pizca de az\xfacar. Cocina 15 minutos a fuego suave.","Fr\xede los huevos y s\xedrvelos encima del pisto, con pan."],t.s)
B.aTk=new A.aT("pisto-huevo","Pisto con huevo frito",35,"2 raciones",B.aiT,B.agE,null,300,13,B.Z,B.e1,!1)
